/// 🪆️ Borrows actual native factory constructor depth and complete catalog capacity without allocating frames.
pub fn bounded_artifact_store_owners_birth_demand<P, Mutation>() -> Result<semio_framework_value::RetirementDemand, ValueError>
where
    P: Clone + ToValue + FromValue + ArtifactPack + semio_framework_value::retirement::RetireOwned + Sync,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + semio_framework_value::retirement::RetireOwned,
{
    let snapshot = BoundedArtifactRetirementFactory::<P>::new();
    let mutation = BoundedArtifactRetirementFactory::<Mutation>::new();
    let depth = semio_framework_value::FactoryRetirement::factory_retirement_depth_demand(&snapshot).max(semio_framework_value::FactoryRetirement::factory_retirement_depth_demand(&mutation)).checked_add(1).ok_or_else(|| ValueError::literal(semio_framework_value::ValueRefusalKind::DepthLimit, "bounded catalog actual factory constructor depth overflow"))?;
    Ok(semio_framework_value::RetirementDemand { capacity_bytes: bounded_artifact_store_owners_birth_bytes::<P, Mutation>(), depth, ..Default::default() })
}

/// 🗃️ The exact typed retirement catalogue for a store whose owner is the FRAMEWORK rather than a
/// plugin app: every factory admits its original owner under independent grants and the cursor disposer is the
/// store's own. `🔌️plugin`'s `bounded_config_store_owners`/`bounded_document_store_owners` are this
/// function — they delegate here rather than carrying a second copy — and
/// `ArtifactCodec::apply_ops_binary`'s throwaway reduction store installs it directly, which is the
/// only catalogue it can have: that thunk is monomorphized over `(P, Mutation)` alone, with no app
/// type in scope to ask `build_document_store_owners()` of (ticket 26/09/18 slices TC3e §7d, TC4).
pub fn bounded_artifact_store_owners<P, Mutation>(grant: RetainedCloneGrant) -> Result<(DocumentStoreOwners<P, Mutation>, RetainedCloneProgress), DocumentStoreOwnersAdmissionError<P, Mutation>>
where
    P: Clone + ToValue + FromValue + ArtifactPack + semio_framework_value::retirement::RetireOwned + Sync,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + semio_framework_value::retirement::RetireOwned,
{
    let bytes = document_store_owners_constructor_birth_bytes::<ArtifactStoreCursorDisposer<P, Mutation>>([
        semio_framework_value::factory_arc_birth_bytes::<BoundedArtifactRetirementFactory<P>>(),
        semio_framework_value::factory_arc_birth_bytes::<BoundedArtifactRetirementFactory<P>>(),
        semio_framework_value::factory_arc_birth_bytes::<BoundedArtifactRetirementFactory<Mutation>>(),
    ]);
    let refusal = if grant.maximum_items == 0 { Some((semio_framework_value::ValueRefusalKind::WorkLimit, "bounded catalog birth requires one admitted item")) }
        else if grant.maximum_depth == 0 { Some((semio_framework_value::ValueRefusalKind::DepthLimit, "bounded catalog birth requires original owner depth")) }
        else if grant.maximum_capacity_bytes < bytes { Some((semio_framework_value::ValueRefusalKind::OwnershipLimit, "bounded catalog birth exceeds admitted native frames")) }
        else { None };
    if let Some((kind, message)) = refusal { return Err(DocumentStoreOwnersAdmissionError { error: ValueError::literal(kind, message), owners: None, progress: Default::default() }); }
    let child = RetainedCloneGrant { maximum_items: grant.maximum_items - 1, maximum_capacity_bytes: grant.maximum_capacity_bytes - bytes, ..grant };
    match DocumentStoreOwners::new(
        Arc::new(BoundedArtifactRetirementFactory::<P>::new()),
        Arc::new(BoundedArtifactRetirementFactory::<P>::new()),
        Arc::new(BoundedArtifactRetirementFactory::<Mutation>::new()),
        Box::new(ArtifactStoreCursorDisposer::<P, Mutation>::new()),
        child,
    ) {
        Ok((owners, mut progress)) => { progress.copied_items += 1; progress.retained_capacity_bytes += bytes; Ok((owners, progress)) }
        Err(mut refusal) => { refusal.progress.copied_items += 1; refusal.progress.retained_capacity_bytes += bytes; Err(refusal) }
    }
}

